package dev.zomboid.decor;
import java.util.*;
public class Checks {
 static int checks;static void check(boolean b,String message){checks++;if(!b)throw new AssertionError(message);}
 public static class Box {public double minX,minY,minZ,maxX,maxY,maxZ;Box(double a,double b,double c,double d,double e,double f){minX=a;minY=b;minZ=c;maxX=d;maxY=e;maxZ=f;}}
 public static class Shape {List<Box> boxes;Shape(Box...b){boxes=Arrays.asList(b);}public List<Box> toAabbs(){return boxes;}}
 public record P(int x,int y,int z){public int getX(){return x;}public int getY(){return y;}public int getZ(){return z;}public P offset(int a,int b,int c){return new P(x+a,y+b,z+c);}public long asLong(){return ((long)x&0x3ffffff)<<38|((long)z&0x3ffffff)<<12|((long)y&0xfff);}}
 public static class B {String id;B(String id){this.id=id;}}
 public static class State {B b;Shape shape;boolean replace;State(String id,Shape sh,boolean replace){b=new B(id);shape=sh;this.replace=replace;}public B getBlock(){return b;}public Shape getShape(Object w,Object p){return shape;}public boolean canBeReplaced(){return replace;}public boolean canBeReplaced(Object c){return replace;}}
 static State air=new State("minecraft:air",new Shape(),true);
 public static class World {Map<P,State> states=new HashMap<>();Map<P,Object> entities=new HashMap<>();Set<P> unloaded=new HashSet<>();int removed,destroyed,updates,sounds;boolean client;long time;public long getGameTime(){return time;}public void playSound(Object player,P p,Object sound,Object source,float volume,float pitch){sounds++;}public boolean hasChunkAt(P p){return !unloaded.contains(p);}public State getBlockState(P p){return states.getOrDefault(p,air);}public Object getBlockEntity(P p){return entities.get(p);}public boolean isClientSide(){return client;}public boolean setBlock(P p,State s,int flags){states.put(p,s);var be=new net.mcreator.doomsdaydecoration.block.entity.AcrateBlockEntity(this,p,s);entities.put(p,be);return true;}public boolean removeBlock(P p,boolean flag){removed++;states.remove(p);entities.remove(p);return true;}public boolean destroyBlock(P p,boolean flag){destroyed++;return removeBlock(p,flag);}public void sendBlockUpdated(P p,Object a,Object b,int flags){updates++;}}
 public static class Part extends B {Part(){super("interaction_part");}public State defaultBlockState(){State s=new State("interaction_part",new Shape(),false);s.b=this;return s;}}
 public static class Context {World w;P p;Context(World w,P p){this.w=w;this.p=p;}public World getLevel(){return w;}public P getClickedPos(){return p;}}
 public static class Item {String id;Item(String s){id=s;}}
 public static class Stack {Item item;String animation;public boolean empty;int count=1;Object custom;public Object get(Object component){return custom;}public void set(Object component,Object value){custom=value;}public void shrink(int n){count-=n;if(count<=0)empty=true;}public Stack(String i,String anim){item=new Item(i);animation=anim;}public boolean isEmpty(){return empty;}public String getUseAnimation(){return animation;}public Item getItem(){return item;}}
 public static class Be {State s;public boolean ddPart;Be(String id){s=new State(id,new Shape(),false);}public State getBlockState(){return s;}}
 public static class Tag {Map<String,Object> m=new HashMap<>();public void putLong(String k,long v){m.put(k,v);}public void putBoolean(String k,boolean v){m.put(k,v);}public void putString(String k,String v){m.put(k,v);}public void putInt(String k,int v){m.put(k,v);}public long getLong(String k){return ((Number)m.getOrDefault(k,0L)).longValue();}public boolean getBoolean(String k){return Boolean.TRUE.equals(m.get(k));}public String getString(String k){return (String)m.getOrDefault(k,"");}public int getInt(String k){return ((Number)m.getOrDefault(k,0)).intValue();}public Tag getCompound(String k){return (Tag)m.getOrDefault(k,new Tag());}public void put(String k,Object v){m.put(k,v);}public boolean contains(String k){return m.containsKey(k);}}
 public static void main(String[] a){
  check(Footprint.cells(List.of(new Box(0,0,0,1,1,1))).isEmpty(),"one-cell object");
  check(Footprint.cells(List.of(new Box(0,0,0,1,2,1))).equals(Set.of(new Footprint.Cell(0,1,0))),"fridge two cells");
  for(Box b:List.of(new Box(0,0,0,2,2,1),new Box(-1,0,0,1,2,1),new Box(0,0,0,1,2,2),new Box(0,0,-1,1,2,1)))check(Footprint.cells(List.of(b)).size()==3,"rotated 2x2 shelf");
  check(Footprint.cells(List.of(new Box(-.25,-1,0,1.25,1.5,1))).size()==8,"vending below controller and overhang");
  check(Footprint.cells(List.of(new Box(0,0,0,1,2,1),new Box(0,0,0,1,2,1))).size()==1,"overlapping shapes deduplicated");
  check(Footprint.cells(List.of(new Box(0,0,0,.8,.2,1))).isEmpty(),"thin object stays in one cell");
  check(Footprint.cells(List.of(new Box(0,0,0,1.000000001,1,1))).isEmpty(),"floating error doesn't occupy next cell");
  for(String id:Storage.IDS){int rows=Storage.rows(id);check(rows>=1&&rows<=6,"legal menu rows: "+id);check(Storage.size(new Be(id))==rows*9,"size matches menu: "+id);}
  check(Storage.rows("acrate")==1,"original crate kept at 9");check(Storage.rows("shelf")==6,"shelf expanded");check(Storage.rows("medicalbox")==2,"small medical box");
  Be normal=new Be("woodencrate"),cooler=new Be("vendingmachine"),part=new Be("interaction_part");part.ddPart=true;
  Stack water=new Stack("minecraft:potion","DRINK"),iron=new Stack("minecraft:iron_ingot","NONE"),ice=new Stack("minecraft:ice","NONE"),packed=new Stack("minecraft:packed_ice","NONE");
  check(Cooling.accepts(normal,0,iron),"general inventory unrestricted");check(Cooling.accepts(cooler,0,water),"water stored");check(!Cooling.accepts(cooler,0,iron),"cooler rejects tool");check(!Cooling.accepts(cooler,26,water),"coolant slot rejects drink");check(Cooling.accepts(cooler,26,ice),"coolant accepts ice");check(Cooling.accepts(cooler,26,packed),"coolant accepts packed ice");check(!Cooling.accepts(part,0,water),"parts cannot hold a second inventory");
  check(Cooling.fuel(ice)==1200&&Cooling.fuel(packed)==6000,"fuel durations");
  Footprint.IDS.add("fridge");World w=new World();P p=new P(10,65,20),q=p.offset(0,1,0);State fridge=new State("fridge",new Shape(new Box(0,0,0,1,2,1)),false);w.states.put(p,fridge);Context ctx=new Context(w,p);
  check(Footprint.validate(ctx,fridge)==fridge,"empty adjacent cell permits placement");w.states.put(q,new State("minecraft:stone",new Shape(),false));check(Footprint.validate(ctx,fridge)==null,"never replace wall");w.states.remove(q);w.unloaded.add(q);check(Footprint.validate(ctx,fridge)==null,"don't load neighboring chunk");w.unloaded.clear();w.entities.put(q,new Object());check(Footprint.validate(ctx,fridge)==null,"don't overwrite container");w.entities.remove(q);
  Footprint.PART=new Part();Footprint.ensure(w,p,fridge);check(w.states.containsKey(q),"created occupied cell");check(Footprint.owned(w,q,p,"fridge"),"owner and root recorded");check(w.updates==1,"client receives links");Footprint.ensure(w,p,fridge);check(w.updates==1,"idempotent registration");
  var be=(net.mcreator.doomsdaydecoration.block.entity.AcrateBlockEntity)w.entities.get(q);Tag t=new Tag();be.ddIce=400;be.ddChill=100;Storage.save(be,t);var copy=new net.mcreator.doomsdaydecoration.block.entity.AcrateBlockEntity(w,q,w.states.get(q));Storage.load(copy,t);check(copy.ddPart&&copy.ddRoot==p.asLong()&&copy.ddOwner.equals("fridge")&&copy.ddIce==400&&copy.ddChill==100,"links and cooling persist");check(Storage.slots(be).length==0,"parts expose no hopper slots");
  check(Footprint.remove(fridge,w,p)==false,"root retains original inventory drop path");check(!w.states.containsKey(q)&&w.destroyed==0,"root removal removes only linked cell");
  w.states.put(q,new State("minecraft:stone",new Shape(),false));Footprint.ensure(w,p,fridge);check(w.getBlockState(q).b.id.equals("minecraft:stone"),"existing overlapping wall untouched");
  w.states.remove(q);Footprint.ensure(w,p,fridge);be=(net.mcreator.doomsdaydecoration.block.entity.AcrateBlockEntity)w.entities.get(q);be.ddOwner="shelf";Footprint.remove(fridge,w,p);check(w.states.containsKey(q),"cleanup never removes a foreign owned part");
  be.ddOwner="fridge";check(Footprint.root(be).equals(p),"part resolves its stored root");w.unloaded.add(p);check(Footprint.root(be)==null,"part never loads root chunk");w.unloaded.clear();be.ddOwner="shelf";check(Footprint.root(be)==null,"part rejects changed root");be.ddOwner="fridge";check(Footprint.remove(w.states.get(q),w,q),"part removal skips its inventory drop");check(w.destroyed==1&&!w.states.containsKey(p),"removing a part destroys the root once");
  World coldWorld=new World();P machine=new P(0,64,0);State vending=new State("vendingmachine",new Shape(),false);var cool=new net.mcreator.doomsdaydecoration.block.entity.AcrateBlockEntity(coldWorld,machine,vending);cool.inventory.put(0,water);cool.inventory.put(26,ice);Tag outer=new Tag(),clock=new Tag();clock.putInt("left",50);outer.put("zomboid_food",clock);water.custom=new net.minecraft.world.item.component.CustomData(outer);Cooling.tick(coldWorld,cool);check(ice.empty&&cool.ddIce==1180,"consumes one ice and one second of fuel");check(cool.ddChill==20&&clock.getInt("cold")==0,"does not cool instantly");Cooling.tick(coldWorld,cool);check(cool.ddIce==1180&&cool.ddChill==20,"repeated tick can't consume twice");for(int i=1;i<10;i++){coldWorld.time=i*20;Cooling.tick(coldWorld,cool);}check(cool.ddChill==200&&clock.getInt("cold")==1200,"ten-second cooling transition");check(clock.getInt("left")==50,"preserves existing food metadata");check(clock.getLong("last")==180&&clock.getInt("rate")==1,"cold timestamp and clock rate");check(cool.changes==10,"cooling fuel saved");cool.ddIce=0;coldWorld.time=200;Cooling.tick(coldWorld,cool);check(cool.ddChill==0,"no energy resets cooling");cool.lootTable=new Object();cool.inventory.put(26,new Stack("minecraft:ice","NONE"));int reads=cool.reads;coldWorld.time=220;Cooling.tick(coldWorld,cool);check(cool.reads==reads,"pending loot never generated by cooling");
  if(a.length>0)try{for(String line:java.nio.file.Files.readAllLines(java.nio.file.Path.of(a[0]))){String[] halves=line.split("\\|");List<Box> boxes=new ArrayList<>();if(!halves[0].isEmpty())for(String box:halves[0].split(";")){double[] v=Arrays.stream(box.split(",")).mapToDouble(Double::parseDouble).toArray();boxes.add(new Box(v[0],v[1],v[2],v[3],v[4],v[5]));}Set<Footprint.Cell> expected=new HashSet<>();if(halves.length>1&&!halves[1].isEmpty())for(String cell:halves[1].split(";")){int[] v=Arrays.stream(cell.split(",")).mapToInt(Integer::parseInt).toArray();expected.add(new Footprint.Cell(v[0],v[1],v[2]));}check(Footprint.cells(boxes).equals(expected),"original model footprint");}}catch(java.io.IOException error){throw new RuntimeException(error);}
  World orphanWorld=new World();orphanWorld.setBlock(q,new State("interaction_part",new Shape(),false),3);var orphan=(net.mcreator.doomsdaydecoration.block.entity.AcrateBlockEntity)orphanWorld.entities.get(q);orphan.ddPart=true;orphan.ddRoot=p.asLong();orphan.ddOwner="fridge";orphanWorld.unloaded.add(p);Footprint.orphan(orphanWorld,q);check(orphanWorld.states.containsKey(q),"unloaded owner is not assumed gone");orphanWorld.unloaded.clear();Footprint.orphan(orphanWorld,q);check(!orphanWorld.states.containsKey(q),"orphan parts cleaned when owner is gone");
  check(Cooling.ticker(w,new State("interaction_part",new Shape(),false))==null,"parts never tick");check(Cooling.ticker(w,new State("shelf",new Shape(),false))==null,"passive storage never ticks");w.client=true;check(Cooling.ticker(w,new State("fridge",new Shape(),false))==null,"cooling is server only");
  System.out.println("Simulated checks passed: "+checks);
 }
}
